WITH matched_keys AS (SELECT supplier_id, brand FROM products EXCEPT DISTINCT SELECT supplier_id, brand FROM products WHERE supplier_id IN (6, 31)), kept_rows AS (SELECT s.* FROM products s JOIN matched_keys k ON s.supplier_id = k.supplier_id AND s.brand = k.brand) SELECT DATE_TRUNC('YEAR', launch_date) AS year_start, MAX(stock_qty) FILTER (WHERE category = 'Fashion') AS fashion_max_stock_qty, STDDEV_SAMP(price) AS price_stddev, APPROX_PERCENTILE(cost, ARRAY(0.25, 0.5, 0.75)) AS cost_quartiles, ROUND(AVG(stock_qty), 2) AS avg_stock_qty, COUNT(DISTINCT supplier_id) AS distinct_supplier_ids, CORR(stock_qty, price) AS corr_stock_qty_price FROM kept_rows GROUP BY 1 ORDER BY corr_stock_qty_price;
